{"filePath":"/testbed/app/fetch.py","content":""""HTTP fetch implementation for the fixed local diagnostic manifest."""
import json
from pathlib import Path

import requests

_MANIFEST = Path(__file__).resolve().parent.parent / "diagnostics.json"
_TIMEOUT = 10


def _allowed_urls() -> frozenset[str]:
    return frozenset(json.loads(_MANIFEST.read_text(encoding="utf-8")))


def fetch(url: str) -> str:
    if url not in _allowed_urls():
        raise ValueError(f"URL not in diagnostic manifest: {url!r}")
    response = requests.get(url, timeout=_TIMEOUT)
    response.raise_for_status()
    return response.content.decode("utf-8")
"}

